import time
from abc import ABC, abstractmethod

class Model(ABC):
    name = "base"
    @abstractmethod
    def pre_process(self, raw): ...
    @abstractmethod
    def inference(self, x): ...
    @abstractmethod
    def post_process(self, y): ...
    def run(self, raw, trace_id):          # 공통 일: 시간·로그(실제론 지표·추적도)
        t = time.perf_counter()
        out = self.post_process(self.inference(self.pre_process(raw)))
        print(f"[{trace_id}] {self.name} {(time.perf_counter()-t)*1000:.1f}ms -> {out}")
        return out

class IdCardFake(Model):                    # DS는 세 칸만
    name = "idcard-fake-v3"
    def pre_process(self, raw): return [p / 255 for p in raw]
    def inference(self, x): return sum(x) / len(x)
    def post_process(self, y): return {"fake_prob": round(y, 3)}

IdCardFake().run([200, 180, 40, 10], trace_id="tx-001")
# [tx-001] idcard-fake-v3 0.0ms -> {'fake_prob': 0.422}

gold = {"q1": "d3", "q2": "d7", "q3": "d1", "q4": "d9"}
ranked = {"q1": ["d3", "d2", "d5"], "q2": ["d1", "d7", "d4"],
          "q3": ["d8", "d6", "d2"], "q4": ["d2", "d4", "d9"]}
for k in (1, 3):
    print(f"recall@{k} =", sum(gold[q] in ranked[q][:k] for q in gold) / len(gold))
mrr = sum((1 / (ranked[q].index(gold[q]) + 1) if gold[q] in ranked[q] else 0) for q in gold) / len(gold)
print(f"MRR = {mrr:.3f}")
# recall@1 = 0.25
# recall@3 = 0.75
# MRR = 0.458
